#[derive(Debug, Clone, Copy, Default, PartialEq, Hash, Eq, FromRepr)]
#[repr(i32)]
pub enum NodeTy {
    #[default]
    N_INVALID = 0,
    /// Entities are world objects with (possible) links to other data sets
    N_ENTITY = 1,
    /// Emitters link to (possibly) deep sources of data (such as loop data sets)
    N_EMITTER = 2,
    /// Boundaries are geometry-only delineations of world-space (postal codes, neighbourhoods, cities, etc.)
    N_BOUNDARY = 3,
}

impl TryFrom<i32> for NodeTy {
    type Error = crate::error::Error;
    fn try_from(v: i32) -> Result<Self, crate::error::Error> {
        NodeTy::from_repr(v).ok_or(crate::error::Error::InvalidEnumValue(v as i64))
    }
}

impl NodeTy {
    pub fn variant_name(&self) -> Option<&'static str> {
        match self {
            Self::N_INVALID => Some("N_INVALID"),
            Self::N_ENTITY => Some("N_ENTITY"),
            Self::N_EMITTER => Some("N_EMITTER"),
            Self::N_BOUNDARY => Some("N_BOUNDARY"),
            _ => None,
        }
    }
}

impl From<NodeTy> for FbsNodeTy {
    fn from(val: NodeTy) -> Self {
        match val {
            NodeTy::N_INVALID => FbsNodeTy::N_INVALID,
            NodeTy::N_ENTITY => FbsNodeTy::N_ENTITY,
            NodeTy::N_EMITTER => FbsNodeTy::N_EMITTER,
            NodeTy::N_BOUNDARY => FbsNodeTy::N_BOUNDARY,
        }
    }
}

impl From<FbsNodeTy> for NodeTy {
    fn from(fbs: FbsNodeTy) -> Self {
        match fbs.0 {
            0 => Self::N_INVALID,
            1 => Self::N_ENTITY,
            2 => Self::N_EMITTER,
            3 => Self::N_BOUNDARY,
            _ => panic!("Invalid value {} when constructing NodeTy", fbs.0),
        }
    }
}

#[derive(Default, PartialEq, Debug, Clone, Hash, Eq)]
pub struct Point {
    pub point_geo: Vec<OrderedFloat<f32>>,
}

impl Point {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsPoint<'a>> {
        use crate::types::generated::entity_generated::PointBuilder as FbsPointBuilder;

        let point_geo_floats = self
            .point_geo
            .iter()
            .map(|f| f.into_inner())
            .collect::<Vec<_>>();
        let point_geo_offset = builder.create_vector(&point_geo_floats);

        let mut bldr = FbsPointBuilder::new(builder);
        bldr.add_point_geo(point_geo_offset);
        bldr.finish()
    }
}

impl From<FbsPoint<'_>> for Point {
    fn from(fbs: FbsPoint<'_>) -> Self {
        let mut point_geo = Vec::new();
        for elem in fbs.point_geo() {
            point_geo.push(elem.into());
        }

        Self { point_geo }
    }
}

impl Point {
    pub fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    pub fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let opts = flatbuffers::VerifierOptions {
            max_tables: 100_000_000,
            ..Default::default()
        };
        let fbs = flatbuffers::size_prefixed_root_with_opts::<FbsPoint>(&opts, bytes)?;
        Ok(Self::from(fbs))
    }
}

