#[derive(Clone, Debug, PartialEq, Hash, Eq)]
pub enum Geometry {
    Point(Point),
    Line(Line),
    MultiLine(MultiLine),
    Polygon(Polygon),
    MultiPolygon(MultiPolygon),
}

impl Default for Geometry {
    fn default() -> Self {
        Self::Point(Point::default())
    }
}

impl Geometry {
    pub fn serialize_to(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder,
    ) -> (WIPOffset<UnionWIPOffset>, FbsGeometry) {
        match self {
            Self::Point(val) => {
                let offset = val.serialize_to(builder).as_union_value();
                let ty = FbsGeometry::Point;
                (offset, ty)
            }
            Self::Line(val) => {
                let offset = val.serialize_to(builder).as_union_value();
                let ty = FbsGeometry::Line;
                (offset, ty)
            }
            Self::MultiLine(val) => {
                let offset = val.serialize_to(builder).as_union_value();
                let ty = FbsGeometry::MultiLine;
                (offset, ty)
            }
            Self::Polygon(val) => {
                let offset = val.serialize_to(builder).as_union_value();
                let ty = FbsGeometry::Polygon;
                (offset, ty)
            }
            Self::MultiPolygon(val) => {
                let offset = val.serialize_to(builder).as_union_value();
                let ty = FbsGeometry::MultiPolygon;
                (offset, ty)
            }
        }
    }
}

