#[derive(Default, PartialEq, Debug, Clone, Hash, Eq)]
pub struct GraphNode {
    /// A human-centric description of this graph node.
    pub _description: Option<String>,
    /// Entity type (ie: traffic loop, road, power line, building, business, demographic data, collision,  ...)
    pub _entity_type: EntityTy,
    /// polygon / line / point / null
    pub _geom: Option<Geometry>,
    /// lat/lng point in space, or centroid if not a point
    pub _location: Option<Point>,
    /// Record id in the data source.
    pub _node_id: Option<GenericId>,
    /// Node type, such as emitter vs. entity
    pub _node_type: NodeTy,
    /// ID of the associated data source
    pub _stream: Option<ObjectId>,
    /// Unique database-specific identifier
    pub _uid: u64,
}

impl GraphNode {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsGraphNode<'a>> {
        use crate::types::generated::entity_generated::GraphNodeBuilder as FbsGraphNodeBuilder;

        let _description_offset = self._description.as_ref().map(|s| builder.create_string(s));
        let _geom_offset = self._geom.as_ref().map(|u| u.serialize_to(builder));
        let _location_offset = self._location.as_ref().map(|o| o.serialize_to(builder));
        let _node_id_offset = self._node_id.as_ref().map(|o| o.serialize_to(builder));
        let _stream_offset = self._stream.as_ref().map(|o| o.serialize_to(builder));

        let mut bldr = FbsGraphNodeBuilder::new(builder);
        if let Some(offset) = _description_offset {
            bldr.add__description(offset);
        }
        bldr.add__entity_type(FbsEntityTy::from(self._entity_type));
        if let Some((offset, ty)) = _geom_offset {
            bldr.add__geom(offset);
            bldr.add__geom_type(ty);
        }
        if let Some(offset) = _location_offset {
            bldr.add__location(offset);
        }
        if let Some(offset) = _node_id_offset {
            bldr.add__node_id(offset);
        }
        bldr.add__node_type(FbsNodeTy::from(self._node_type));
        if let Some(offset) = _stream_offset {
            bldr.add__stream(offset);
        }
        bldr.add__uid(self._uid);
        bldr.finish()
    }
}

impl From<FbsGraphNode<'_>> for GraphNode {
    fn from(fbs: FbsGraphNode<'_>) -> Self {
        let _description = fbs._description().map(ToOwned::to_owned);
        let _entity_type = EntityTy::from(fbs._entity_type());
        let _geom = if let Some(val) = fbs._geom() {
            let _geom = match fbs._geom_type() {
                FbsGeometry::Point => Geometry::Point(Point::from(fbs._geom_as_point().unwrap())),
                FbsGeometry::Line => Geometry::Line(Line::from(fbs._geom_as_line().unwrap())),
                FbsGeometry::MultiLine => {
                    Geometry::MultiLine(MultiLine::from(fbs._geom_as_multi_line().unwrap()))
                }
                FbsGeometry::Polygon => {
                    Geometry::Polygon(Polygon::from(fbs._geom_as_polygon().unwrap()))
                }
                FbsGeometry::MultiPolygon => Geometry::MultiPolygon(MultiPolygon::from(
                    fbs._geom_as_multi_polygon().unwrap(),
                )),
                _ => unreachable!(),
            };

            Some(_geom)
        } else {
            None
        };

        let _location = fbs._location().map(Point::from);
        let _node_id = fbs._node_id().map(GenericId::from);
        let _node_type = NodeTy::from(fbs._node_type());
        let _stream = fbs._stream().map(ObjectId::from);
        let _uid = fbs._uid();
        Self {
            _description,
            _entity_type,
            _geom,
            _location,
            _node_id,
            _node_type,
            _stream,
            _uid,
        }
    }
}

impl GraphNode {
    pub fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    pub fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let opts = flatbuffers::VerifierOptions {
            max_tables: 100_000_000,
            ..Default::default()
        };
        let fbs = flatbuffers::size_prefixed_root_with_opts::<FbsGraphNode>(&opts, bytes)?;
        Ok(Self::from(fbs))
    }
}

